              onInput=${e => setTitle(e.target.value)} onKeyDown=${addOnEnter} /></label>
          <button type="button" class="space-button--primary" onClick=${add}
            disabled=${save.state === 'saving' || !title.trim()}>Add to library</button>
        </div>
