import { statusOf, priorityOf } from './ui.js';

function time(value) {
  return value ? new Date(value * 1000).toLocaleString() : 'Not available yet';
}

export function Overview({ records, runs }) {
  const total = records.length;
  const count = status => records.filter(record => statusOf(record) === status).length;
  const queued = count('queued');
  const reading = count('reading');
  const done = count('done');
  const waiting = records.filter(record => priorityOf(record) === 'high' && statusOf(record) !== 'done').length;
  const latest = runs[0];
  const success = runs.find(run => run.status === 'succeeded');
  const stats = [['In library', total, 'book'], ['Queued', queued, 'list'], ['Reading', reading, 'play'], ['Completed', done, 'check']];
  const bars = [['Queued', queued], ['Reading', reading], ['Completed', done]];
  const share = n => (total ? Math.round((n / total) * 100) : 0);
  return html`
    <section class="view" aria-labelledby="overview-heading">
      <h2 id="overview-heading">Overview</h2>
      <div class="space-stat-grid">
        ${stats.map(([label, n, icon]) => html`
          <div class="space-card space-stat" key=${label}>
            <span class="space-stat-label">${label}</span>
            <span class="space-tile space-tile--small" data-accent="blue" aria-hidden="true"><span class="space-icon" data-icon=${icon}></span></span>
            <strong class="space-stat-value">${n}</strong>
          </div>`)}
      </div>
      ${!total && html`<${EmptyState} title="Start your reading library">
        <p>Nothing is saved yet. Add a paper in Library, or use Refresh to pull the public feed once Refresh is permitted in this Space's Permissions.</p>
        <//>`}
      ${total > 0 && html`
        <div class="space-split">
          <figure class="space-chart">
            <figcaption>Papers by status · ${total} papers in library</figcaption>
            <div class="space-chart-plot status-bars" role="img"
              aria-label=${`Queued ${queued}, reading ${reading}, completed ${done}, out of ${total} papers.`}>
              ${bars.map(([label, n]) => html`
                <div class="bar-row" key=${label}>
                  <span>${label}</span>
                  <span class="bar-track"><span class="bar-fill" style=${{ width: share(n) + '%' }}></span></span>
                  <span class="space-number">${n} (${share(n)}%)</span>
                </div>`)}
            </div>
            <p class="space-caption">Bar length is each status as a share of all ${total} papers, from a zero baseline.</p>
          </figure>
          <section class="space-card" aria-labelledby="next-heading">
            <h3 id="next-heading">Ready for review</h3>
            ${waiting ? html`
              <p>${waiting} high-priority ${waiting === 1 ? 'paper is' : 'papers are'} not yet completed.</p>
              <p><a class="space-button space-button--primary" href="#/review">Start reviewing</a></p>` : html`
              <p class="space-muted">No high-priority papers are waiting. Set a paper's priority to High in Library or Queue to see it in Review.</p>`}
          </section>
        </div>`}
      <section class="space-card" aria-labelledby="freshness-heading">
        <h3 id="freshness-heading">Public source freshness</h3>
        <dl class="space-facts">
          <dt>Last attempt</dt><dd>${latest ? `${time(latest.started_at || latest.queued_at)} (${latest.status})` : 'Never run'}</dd>
          <dt>Last successful refresh</dt><dd>${success ? time(success.ended_at) : 'No success in recent history'}</dd>
          <dt>Source as of</dt><dd>${success ? time(success.source_as_of) : 'Not available yet'}</dd>
        </dl>
        ${latest && ['failed', 'blocked', 'canceled'].includes(latest.status) && html`
          <p class="space-notice space-notice--error" role="alert">Refresh ${latest.status}. ${latest.error || latest.detail?.reason || 'Open run details in the host.'}
            Existing records and notes remain available.</p>`}
        <p class="space-caption">Refresh only runs when it is permitted in this Space's Permissions. This view uses the latest 50 runs; the host shows complete freshness information.</p>
      </section>
    </section>`;
