import { html, useSaveState, SaveIndicator, EmptyState } from 'spaces-kit';
import { statusOf, priorityOf, STATUS_LABEL } from './ui.js';

// Review: high-priority papers that are not done, one at a time. No <form>: explicit JS handlers only.
const label = STATUS_LABEL;

export function Review({ records, reload }) {
  const [selectedId, setSelectedId] = useState(null);
  const [conflict, setConflict] = useState(null);
  const lastIndex = useRef(0);
  const save = useSaveState();
  const queue = records
    .filter(record => priorityOf(record) === 'high' && statusOf(record) !== 'done')
    .sort((a, b) => a.created_at - b.created_at);
  const found = queue.findIndex(record => record.id === selectedId);
  const index = found >= 0 ? found : Math.min(lastIndex.current, Math.max(queue.length - 1, 0));
  const current = queue[index];
  if (current) lastIndex.current = index;

  const go = step => {
    if (!queue.length || save.state === 'saving') return;
    const next = queue[(index + step + queue.length) % queue.length];
    setSelectedId(next.id);
    setConflict(null);
  };
  const mark = async status => {
    if (!current || save.state === 'saving' || statusOf(current) === status) return;
    await save.run(async () => {
      try {
        const saved = await window.space.put('papers', current.id, { status }, { baseRev: current.rev });
        setConflict(null);
        // A finished paper leaves this view; keep the same position so the next one is shown.
        if (status === 'done') setSelectedId(null);
        reload();
        return saved;
      } catch (error) {
        if (error.code === 'conflict') setConflict(error);
        throw error;
      }
    });
  };

  return html`
    <section class="view" aria-labelledby="review-heading">
      <h2 id="review-heading">Review</h2>
      <p class="view-intro">Work through high-priority papers that are not completed, one at a time.</p>
      ${current ? html`
        <div class="space-card space-stack" role="group" aria-label="Paper under review">
          <p class="space-caption">Paper ${index + 1} of ${queue.length} · ${label[statusOf(current)] || statusOf(current)} · High priority${current.data.demo ? ' · demo' : ''}</p>
          <div>
            <h3 class="editor-title">${window.space.field(current, 'title') || 'Untitled'}</h3>
            ${window.space.field(current, 'authors') && html`<p class="space-caption">${window.space.field(current, 'authors')}</p>`}
          </div>
          <p class="summary">${window.space.field(current, 'summary') || 'No summary supplied.'}</p>
          <div>
            <h4>Your saved notes</h4>
            <p class="summary review-notes">${current.data.notes || 'No notes saved yet. Add some in Library or Queue.'}</p>
          </div>
          <div class="space-actions">
            <button type="button" onClick=${() => go(-1)} disabled=${queue.length < 2 || save.state === 'saving'}>Previous</button>
            <button type="button" onClick=${() => go(1)} disabled=${queue.length < 2 || save.state === 'saving'}>Next</button>
            <button type="button" onClick=${() => mark('reading')}
              disabled=${save.state === 'saving' || statusOf(current) === 'reading'}>Mark reading</button>
            <button type="button" class="space-button--primary" onClick=${() => mark('done')} disabled=${save.state === 'saving'}>Mark done</button>
          </div>
          <${SaveIndicator} state=${save.state} message=${save.message} />
          ${conflict && html`
            <div class="space-conflict" role="alert">This paper changed elsewhere (now ${label[statusOf(conflict.current)] || statusOf(conflict.current)}). Nothing was overwritten.
              <button type="button" onClick=${() => setConflict(null)}>Show latest</button></div>`}
        </div>` : html`
        <${EmptyState} title="Nothing to review">
          <p>Review shows papers whose priority is High and whose status is not Completed. Right now there are none.</p>
          <p>To fill it, open a paper in Library or Queue and set its priority to High (and leave it Queued or Reading). Marking a paper done here removes it from this view; it stays in Library.</p><//>`}
    </section>`;
