{"ok": true, "result": {"path": "views/ui.js", "text": "import { html } from 'spaces-kit';

export const STATUS_LABEL = { queued: 'Queued', reading: 'Reading', done: 'Completed' };
export const PRIORITY_LABEL = { high: 'High', normal: 'Normal', low: 'Low' };
export const statusOf = record => record.data.status || 'queued';
export const priorityOf = record => record.data.priority || 'normal';

// Status always carries a word; the check icon is supplemental.
export function StatusBadge({ record }) {
  const status = statusOf(record);
  const label = STATUS_LABEL[status] || status;
  if (status === 'done') {
    return html`<span class="space-badge space-badge--success"><span class="space-icon" data-icon="check" aria-hidden="true"></span>${label}</span>`;
  }
  if (status === 'queued') return html`<span class="space-badge space-badge--pending">${label}</span>`;
  return html`<span class="space-badge">${label}</span>`;
}

export function PriorityBadge({ record }) {
  const priority = priorityOf(record);
  const cls = priority === 'high' ? 'space-badge space-badge--warning' : 'space-badge';
  return html`<span class=${cls}>${PRIORITY_LABEL[priority] || priority} priority</span>`;
}", "size": 1139, "sha": "930744e90c4af0ca2db19c2d82c2fb3f43af50b7b0daacdc6962403bfe0249ef", "rev": 8}}

